// ── Summary in one line ──
// Provider gives you DI through the widget tree.
// Riverpod gives you DI as a typed, reactive graph that happens to render UI.

// Roughly what context.watch<T>() expands to inside the provider package
T watch<T>(BuildContext context) {
  final element = context
      .dependOnInheritedWidgetOfExactType<_InheritedProviderScope<T?>>();
  return element!.value as T;      // dependency registered -> rebuild on notify
}

// read<T>() — same lookup, no dependency, so it is safe outside build()
T read<T>(BuildContext context) {
  final element = context
      .getElementForInheritedWidgetOfExactType<_InheritedProviderScope<T?>>();
  return (element!.widget as dynamic).value as T;
}

// ── Exact-type lookup: the most common wiring bug ──
abstract class AuthNotifier extends ChangeNotifier { void signOut(); }
class AuthNotifierImpl extends AuthNotifier { @override void signOut() {} }

