class FeedNotifier extends ChangeNotifier {
  FeedNotifier(this._repo) {
    _sub = _repo.updates().listen((_) => notifyListeners());
  }

  final FeedRepository _repo;
  late final StreamSubscription<void> _sub;
  bool _disposed = false;
  List<Post> posts = const [];

  Future<void> load() async {
    final fresh = await _repo.fetch();   // user may pop the screen mid-flight
    if (_disposed) return;               // ✅ guard the async gap
    posts = fresh;
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _sub.cancel();                       // ✅ stop the source first
    super.dispose();
  }
}

// ✅ Provider owns the notifier — do not dispose it yourself
ChangeNotifierProvider(create: (_) => FeedNotifier(repo)..load());

