    super.dispose();
  }
  @override
  Widget build(BuildContext context) =>
      ChangeNotifierProvider.value(value: n, child: const FeedView());
}

// ✅ Widget side: check mounted after an await
Future<void> _submit(BuildContext context) async {
  await context.read<FeedNotifier>().load();
  if (!context.mounted) return;
  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Done')));
}

