class SettingsNotifier extends ChangeNotifier {
  bool _darkMode = false;
  bool get darkMode => _darkMode;
  set darkMode(bool v) {
    if (v == _darkMode) return;
    _darkMode = v;
    notifyListeners();              // this is what marks dependents dirty
  }
}

