class FeedNotifier extends ChangeNotifier {
  FeedNotifier(this._repo);
  final FeedRepository _repo;
  String? _token;
  Timer? _poll;
  List<Post> posts = const [];

  // update() hands the new dependency to the object that already exists
  void updateAuth(String? token) {
    if (token == _token) return;
    _token = token;
    _poll ??= Timer.periodic(const Duration(minutes: 1), (_) => refresh());
  }

  Future<void> refresh() async {
    posts = await _repo.fetch(_token);
    notifyListeners();
  }

  @override
  void dispose() {
    _poll?.cancel();
    super.dispose();
  }
}

// ❌ update as a factory: every token change orphans the previous notifier
ChangeNotifierProxyProvider<AuthNotifier, FeedNotifier>(
  create: (_) => FeedNotifier(repo),
  update: (_, auth, __) => FeedNotifier(repo)..updateAuth(auth.token),
);  // the discarded instance keeps its Timer — dispose() never runs on it

// ✅ update reconfigures the object create made
MultiProvider(
  providers: [
    ChangeNotifierProvider(create: (_) => AuthNotifier()),   // dependency first
    ChangeNotifierProxyProvider<AuthNotifier, FeedNotifier>( // then the proxy
      create: (_) => FeedNotifier(repo),
      update: (_, auth, previous) => previous!..updateAuth(auth.token),
    ),
  ],
  child: const App(),
);

class _CheckoutPageState extends State<CheckoutPage> {
  late final CheckoutNotifier _notifier = context.read<CheckoutNotifier>();
  late CheckoutStatus _last;

  @override
  void initState() {
    super.initState();
    _last = _notifier.status;
    _notifier.addListener(_onChanged);        // subscribe outside build
  }

  void _onChanged() {
    final status = _notifier.status;
    if (status == _last) return;              // react to transitions, not ticks
    _last = status;
    if (!mounted) return;
    if (status == CheckoutStatus.paid) {
      Navigator.of(context).pushReplacementNamed('/receipt');
    } else if (status == CheckoutStatus.failed) {
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text(_notifier.error!)));
    }
  }

  @override
  void dispose() {
    _notifier.removeListener(_onChanged);     // symmetric, always
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => const CheckoutForm();
}

// ❌ The same effect from build
Widget build(BuildContext context) {
  final status = context.watch<CheckoutNotifier>().status;
  if (status == CheckoutStatus.failed) {
    // throws during build, and repeats on every unrelated rebuild:
    // parent rebuild, keyboard, theme change, hot reload
    ScaffoldMessenger.of(context)
        .showSnackBar(const SnackBar(content: Text('Payment failed')));
  }
  return const CheckoutForm();
}

