// The session boundary: everything user-specific lives under a key
class SignedInScope extends StatelessWidget {
  const SignedInScope({super.key, required this.child});
  final Widget child;

  @override
  Widget build(BuildContext context) {
    final userId = context.select<AuthNotifier, String?>((a) => a.userId);
    if (userId == null) return const SignInPage();

    return KeyedSubtree(
      key: ValueKey(userId),        // new id -> old elements unmount,
      child: MultiProvider(         // notifiers dispose, create runs again
        providers: [
          ChangeNotifierProvider(create: (c) => CartNotifier(c.read<Dio>())),
          ChangeNotifierProvider(create: (c) => FeedNotifier(c.read<Dio>())),
        ],
        child: child,
      ),
    );
  }
}

// Notifiers must tolerate being disposed mid-request
class CartNotifier extends ChangeNotifier {
