class ProfileNotifier extends ChangeNotifier {
  String name = '';
  String email = '';
  int age = 0;

  // ❌ Three synchronous dispatches; the UI still rebuilds exactly once
  void applyChatty(Profile p) {
    name = p.name;   notifyListeners();
    email = p.email; notifyListeners();
    age = p.age;     notifyListeners();
  }

  // ✅ Mutate, then notify once
  void apply(Profile p) {
    name = p.name;
    email = p.email;
    age = p.age;
    notifyListeners();
  }
}

// What the extra dispatches really pay for
class NameLabel extends StatelessWidget {
  const NameLabel({super.key});
  @override
  Widget build(BuildContext context) {
    // the selector runs on EVERY notification, in every mounted screen;
    // the widget rebuilds only when the selected slice changes by ==
    final name = context.select<ProfileNotifier, String>((p) => p.name);
    return Text(name);
  }
}

// Non-widget listeners get no coalescing at all
void wire(ProfileNotifier profile) {
  profile.addListener(() => analytics.log('profile_changed'));   // 3 events
  profile.addListener(() => prefs.setString('name', profile.name)); // 3 writes
  profile.applyChatty(Profile.demo);
  // one frame, one rebuild, six side effects
}

// A notifier above MaterialApp: every mounted route can depend on it
class ClockNotifier extends ChangeNotifier {
  ClockNotifier() {
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      now = DateTime.now();
      notifyListeners();          // marks EVERY dependent in the stack dirty
    });
  }
  late final Timer _timer;
  DateTime now = DateTime.now();

  @override
  void dispose() { _timer.cancel(); super.dispose(); }
}

// ❌ Each screen watches the whole notifier and rebuilds at 1 Hz,
// including the four screens buried under the current route
class OrderPage extends StatelessWidget {
  const OrderPage({super.key});
